  /* ---- sumo kanji (preselected) ---- */
  MD.KANJI = [
    { ch:"\u529b", label:"Power" }, { ch:"\u52dd", label:"Victory" }, { ch:"\u9b42", label:"Spirit" },
    { ch:"\u5f37", label:"Strong" }, { ch:"\u731b", label:"Fierce" }, { ch:"\u5805", label:"Steady" },
    { ch:"\u9f8d", label:"Dragon" }, { ch:"\u864e", label:"Tiger" }, { ch:"\u96f7", label:"Thunder" },
    { ch:"\u5c71", label:"Mountain" }, { ch:"\u706b", label:"Fire" }, { ch:"\u6c34", label:"Water" },
    { ch:"\u98a8", label:"Wind" }, { ch:"\u6c37", label:"Ice" }, { ch:"\u4f8d", label:"Samurai" },
    { ch:"\u6607", label:"Rising" }, { ch:"\u5fc3", label:"Heart" }, { ch:"\u661f", label:"Star" }
  ];

  /* ---- decoration libraries (extensible) ---- */
  MD.TEXTURES    = [ { id:"tex02", label:"Waves", vb:A.TEX.vb, svg:A.TEX.inner } ];
  MD.BACKGROUNDS = [ { id:"bg04",  label:"Diamond", vb:A.BG.vb, svg:A.BG.inner } ];
  MD.FOREGROUNDS = [ { id:"fg26",  label:"Shards", vb:A.FG.vb, svg:A.FG.inner } ];

  MD.PALETTE = [
    "#957b91","#66335b","#4f2347","#9e1b8b","#c2477d","#b83a3a","#7458b3","#2a5aa0",
    "#2f6f5e","#c9932f","#b59326","#fcee21","#d8b25a","#e8e2d2","#f4ecd8","#1c1e26","#0d0f15","#dcd3da"
  ];

  MD.DEFAULT = {
    v: 2,
    belt:   "#957b91",
    fringe: "#fcee21",                 // high-light; low-light derived darker
    body:   "#dcd3da",
    texture: null,                     // { id, color, opacity, x, y, s, r }
    bg:      null,                     // { id, color, opacity, x, y, s, r }
    fg:      null,                     // { id, color, opacity, x, y, s, r }
    kanji:   { ch:"\u529b", color:"#4f2347", x:200, y:300, s:1, r:0 }
  };

  function clone(o){ return JSON.parse(JSON.stringify(o)); }
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]; }); }
  function byId(list, id){ for (var i=0;i<list.length;i++) if (list[i].id===id) return list[i]; return null; }

  // multiply a hex colour toward black -> guaranteed darker (fringe low-light)
  function darken(hex, f){
    f = (f==null?0.4:f);
    var m=/^#?([0-9a-f]{6})$/i.exec(String(hex||"").trim());
    if(!m) return "#000000";
    var n=parseInt(m[1],16), r=(n>>16)&255, g=(n>>8)&255, b=n&255;
    r=Math.round(r*(1-f)); g=Math.round(g*(1-f)); b=Math.round(b*(1-f));
    return "#"+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
  }

  // place a decoration asset (its own viewBox W H) centred at (cx,cy) on the
  // 400x600 canvas, with scale k, rotation r, colour + opacity.
  function placeDeco(asset, layer){
    var wh=(asset.vb||"0 0 100 100").split(/\s+/), W=+wh[2], H=+wh[3];
    var cx=layer.x!=null?layer.x:200, cy=layer.y!=null?layer.y:300;
    var k=layer.s!=null?layer.s:1, r=layer.r||0, op=layer.opacity!=null?layer.opacity:1;
    return '<g opacity="'+op+'" fill="'+esc(layer.color||"#000")+'" '+
      'transform="translate('+cx+','+cy+') rotate('+r+') scale('+k+') translate('+(-W/2)+','+(-H/2)+')">'+
      asset.svg+'</g>';
  }

  /* ============================================================
     RENDER
     ============================================================ */
  MD.renderSVG = function (design, opts) {
    design = design || MD.DEFAULT;
    if (design.v !== 2) design = MD.DEFAULT;   // legacy v1 saves render as the new default
    opts = opts || {};
    var variant = opts.variant || "chip";     // 'chip' (square, fits whole) | 'full' (2:3)
    var size = opts.size || 64;

    var body = esc(design.body || "#dcd3da");
    var belt = esc(design.belt || "#957b91");
    var hi   = design.fringe || "#fcee21";
    var lo   = darken(hi, 0.42);

    var uid = "mw" + Math.random().toString(36).slice(2,8);

    // --- clip silhouette = Layer 4 apron ---
    var clip = '<clipPath id="'+uid+'">'+A.L4.main+'</clipPath>';

    // --- decoration sub-layers (clipped to apron) ---
    var deco = "";
    if (design.texture){ var t=byId(MD.TEXTURES, design.texture.id); if(t) deco += placeDeco(t, design.texture); }
    if (design.bg){ var bb=byId(MD.BACKGROUNDS, design.bg.id); if(bb) deco += placeDeco(bb, design.bg); }
    if (design.fg){ var ff=byId(MD.FOREGROUNDS, design.fg.id); if(ff) deco += placeDeco(ff, design.fg); }
    if (design.kanji && design.kanji.ch){
      var k=design.kanji, kx=k.x!=null?k.x:200, ky=k.y!=null?k.y:300, ks=k.s!=null?k.s:1, kr=k.r||0;
      deco += '<g transform="translate('+kx+','+ky+') rotate('+kr+') scale('+ks+')">'+
        '<text x="0" y="0" text-anchor="middle" dominant-baseline="central" '+
        'font-family="\'Zen Kaku Gothic New\',\'Hiragino Kaku Gothic ProN\',serif" font-weight="900" '+
        'font-size="150" fill="'+esc(k.color||"#4f2347")+'">'+esc(k.ch)+'</text></g>';
    }

    var art =
      '<g fill="'+body+'">'+A.L6.main+'</g>'+
      '<g fill="'+body+'">'+A.L5.main+'</g>'+
      '<g fill="'+body+'">'+A.L4.main+'</g>'+
      '<g clip-path="url(#'+uid+')">'+deco+'</g>'+
      '<g fill="'+esc(lo)+'">'+A.L3.main+'</g>'+
      '<g fill="'+esc(hi)+'">'+A.L2.main+'</g>'+
      (A.L2.accent ? '<g fill="#ffffff">'+A.L2.accent+'</g>' : '')+
      '<g fill="'+belt+'">'+A.L1.main+'</g>';

    if (variant === "full"){
      return '<svg viewBox="0 0 400 600" width="'+size+'" height="'+Math.round(size*1.5)+'" '+
        'xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Team mawashi avatar">'+
        '<defs>'+clip+'</defs>'+art+'</svg>';
    }
    // chip: whole mawashi fitted into a square box
    return '<svg viewBox="0 0 400 600" width="'+size+'" height="'+size+'" preserveAspectRatio="xMidYMid meet" '+
      'xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Team mawashi avatar">'+
      '<defs>'+clip+'</defs>'+art+'</svg>';
  };

